module pulse_detect #(
    parameter s0 = 2'b00,
    parameter s1 = 2'b01,
    parameter s2 = 2'b10,
    parameter s3 = 2'b11
) (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);
	reg [1:0] state, next_state;

	always@(posedge clk or negedge rst_n) begin
		if(!rst_n) state <= s0;
		else 		 state <= next_state;
	end

	always@(*) begin
		case(state)
			s0:	begin
				next_state = (data_in)? s0 : s1;
			end
			s1:	begin
				next_state = (data_in)? s2 : s1;
			end
			s2:	begin
				next_state = (data_in)? s0 : s3;
			end
			s3:	begin
				next_state = (data_in)? s2 : s1;
			end
			default:	next_state = s0;
		endcase
	end

	always@(*) begin
		data_out = ((state==s2)&&(data_in==1'b0))? 1'b1 : 1'b0;
	end
endmodule
